      ["min"] = 1,
      ["race"] = 255,
      ["start"] = { ["U"] = { 900200 } },
      ["end"] = { ["U"] = { 900200 } },
    }
  end
  -- its display name must exist in the quest locale table or it renders blank
  if pfDB["quests"]["enUS-turtle"] and not pfDB["quests"]["enUS-turtle"][700001] then
    pfDB["quests"]["enUS-turtle"][700001] = { ["T"] = "Oink, Oink!" }
  end
end

